// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type XAUUSDChartProps = Record<string, any>;

// Data structure: Open, Close, High, Low (on a normalized 0-120 price scale)
// Support is at Price = 50
const CANDLES = [
  { o: 80, c: 70, h: 82, l: 68 }, // F 0-15
  { o: 70, c: 60, h: 72, l: 58 }, // F 15-30
  { o: 60, c: 52, h: 63, l: 51 }, // F 30-45
  { o: 52, c: 50.2, h: 54, l: 50 }, // F 45-60 (Approaching support)
  { o: 50.2, c: 54, h: 56, l: 50 }, // F 60-75 (Bounce 1)
  { o: 54, c: 51, h: 55, l: 50.5 }, // F 75-90
  { o: 51, c: 55, h: 57, l: 50.2 }, // F 90-105 (Bounce 2)
  { o: 55, c: 51, h: 56, l: 50.5 }, // F 105-120 (Tension)
  { o: 51, c: 35, h: 52, l: 20 }, // F 120-135 (THE BREAKDOWN - Liquidity Grab)
  { o: 35, c: 58, h: 60, l: 30 }, // F 135-150 (THE ENGULF - Reversal)
  { o: 58, c: 75, h: 78, l: 56 }, // F 150-165 (Rally)
  { o: 75, c: 95, h: 98, l: 73 }, // F 165-180 (Aggressive Rally)
  { o: 95, c: 115, h: 118, l: 93 }, // F 180-195 (Aggressive Rally)
];

const STAGGER_FRAMES = 15;

const XAUUSDChart: React.FC<XAUUSDChartProps> = ({
  backgroundColor = "#060608",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "XAUUSD",
  subtitle = "LIQUIDITY GRAB | 15M",
  bullColor = "#00e676",
  bearColor = "#ff1744",
  supportColor = "#ffd700",
  flashColor = "#ff1744",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const chartLeft = width * 0.1;
  const chartRight = width * 0.8;
  const chartWidth = chartRight - chartLeft;
  const step = chartWidth / CANDLES.length;
  const candleWidth = step * 0.6;

  // Mapping price to Y pixel coordinates (0-120 scale)
  const mapPriceToY = (price: number) => {
    return interpolate(price, [0, 120], [height * 0.85, height * 0.25]);
  };

  const supportY = mapPriceToY(50);

  // Cinematic Camera Movement
  const cameraScale = interpolate(
    frame,
    [0, 100, 125, 160, 240, 300],
    [1.0, 1.0, 1.25, 1.25, 0.85, 0.8],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const cameraPanY = interpolate(
    frame,
    [0, 100, 125, 160, 240, 300],
    [0, 0, -40, -40, 200, 250],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Calculate current active price for the indicator pill
  let currentActivePrice = CANDLES[0].o;
  let activeColor = bearColor;
  for (let i = 0; i < CANDLES.length; i++) {
    const startFrame = i * STAGGER_FRAMES;
    const endFrame = startFrame + STAGGER_FRAMES;
    if (frame >= startFrame && frame <= endFrame) {
      currentActivePrice = interpolate(frame, [startFrame, endFrame], [CANDLES[i].o, CANDLES[i].c], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      activeColor = CANDLES[i].c > CANDLES[i].o ? bullColor : bearColor;
    } else if (frame > endFrame) {
      currentActivePrice = CANDLES[i].c;
      activeColor = CANDLES[i].c > CANDLES[i].o ? bullColor : bearColor;
    }
  }
  const currentPriceY = mapPriceToY(currentActivePrice);
  const displayPriceString = (1975 + currentActivePrice * 0.5).toFixed(2);

  // Event Triggers
  // Breakdown happens between 120-135.
  const flashZoneOpacity = interpolate(frame, [123, 128, 140, 150], [0, 0.15, 0.15, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  // Engulfing candle closes back above support around 145.
  const pulseOpacity = interpolate(frame, [143, 148, 165, 185], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pulseScaleY = interpolate(frame, [143, 150, 175], [1, 5, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Background Grid Setup
  const gridLines = [20, 40, 60, 80, 100, 120];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      {/* Background Watermark */}
      <div
        style={{
          position: "absolute",
          top: "40%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          fontSize: 180,
          fontWeight: 900,
          color: "white",
          opacity: 0.02,
          whiteSpace: "nowrap",
          letterSpacing: "-0.05em",
        }}
      >
        {title}
      </div>

      {/* Camera Container */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          transform: `scale(${cameraScale}) translateY(${cameraPanY}px)`,
          transformOrigin: `50% ${supportY}px`,
        }}
      >
        {/* Grid Lines */}
        {gridLines.map((priceLevel) => (
          <div
            key={`grid-${priceLevel}`}
            style={{
              position: "absolute",
              top: mapPriceToY(priceLevel),
              left: chartLeft,
              width: chartWidth,
              height: 1,
              backgroundColor: "white",
              opacity: 0.04,
            }}
          />
        ))}

        {/* Support Line */}
        <div
          style={{
            position: "absolute",
            top: supportY,
            left: chartLeft - 20,
            width: chartWidth + 40,
            height: 2,
            backgroundColor: supportColor,
            boxShadow: `0 0 10px 1px ${supportColor}`,
            opacity: 0.8,
          }}
        />

        {/* Support Gold Pulse (Confirmation) */}
        <div
          style={{
            position: "absolute",
            top: supportY - 2,
            left: chartLeft - 20,
            width: chartWidth + 40,
            height: 4,
            backgroundColor: supportColor,
            boxShadow: `0 0 30px 10px ${supportColor}`,
            opacity: pulseOpacity,
            transform: `scaleY(${pulseScaleY})`,
            borderRadius: "50%",
          }}
        />

        {/* Red Flash Zone (Stop Loss Hunt) */}
        <div
          style={{
            position: "absolute",
            top: supportY,
            left: chartLeft - 20,
            width: chartWidth + 40,
            height: mapPriceToY(0) - supportY + 100,
            backgroundColor: flashColor,
            opacity: flashZoneOpacity,
            boxShadow: `inset 0 30px 50px -20px ${flashColor}`,
          }}
        />

        {/* Candlesticks */}
        {CANDLES.map((c, i) => {
          const startFrame = i * STAGGER_FRAMES;
          const drawProgress = interpolate(
            frame - startFrame,
            [0, STAGGER_FRAMES - 3],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          if (drawProgress === 0) return null;

          const currClose = interpolate(drawProgress, [0, 1], [c.o, c.c]);
          const currHigh = interpolate(drawProgress, [0, 1], [c.o, c.h]);
          const currLow = interpolate(drawProgress, [0, 1], [c.o, c.l]);

          const topPrice = Math.max(c.o, currClose);
          const bottomPrice = Math.min(c.o, currClose);

          const topY = mapPriceToY(topPrice);
          const bottomY = mapPriceToY(bottomPrice);
          const highY = mapPriceToY(currHigh);
          const lowY = mapPriceToY(currLow);

          const isBull = c.c > c.o;
          const color = isBull ? bullColor : bearColor;
          const xPos = chartLeft + i * step + step / 2;

          return (
            <div key={`candle-${i}`} style={{ position: "absolute", left: xPos, top: 0, width: candleWidth }}>
              {/* Wick */}
              <div
                style={{
                  position: "absolute",
                  left: candleWidth / 2 - 1,
                  width: 2,
                  top: highY,
                  height: Math.max(1, lowY - highY),
                  backgroundColor: color,
                  borderRadius: 2,
                }}
              />
              {/* Body */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  width: candleWidth,
                  top: topY,
                  height: Math.max(2, bottomY - topY),
                  backgroundColor: color,
                  borderRadius: 4,
                  boxShadow: `0 0 8px 0 ${color}40`,
                }}
              />
            </div>
          );
        })}

        {/* Current Price Axis Pill */}
        <div
          style={{
            position: "absolute",
            top: currentPriceY - 14,
            left: chartRight + 15,
            backgroundColor: activeColor,
            padding: "6px 12px",
            borderRadius: 6,
            color: "#000",
            fontWeight: 800,
            fontSize: 16,
            boxShadow: `0 4px 15px ${activeColor}60`,
            display: "flex",
            alignItems: "center",
          }}
        >
          {/* Tracker Line to Axis */}
          <div
            style={{
              position: "absolute",
              left: -15 - chartWidth,
              width: chartWidth + 15,
              height: 1,
              borderTop: `1px dashed ${activeColor}`,
              top: "50%",
              opacity: 0.5,
            }}
          />
          {displayPriceString}
        </div>
      </div>

      {/* Static UI Overlay */}
      <div style={{ position: "absolute", top: height * 0.08, left: width * 0.08, display: "flex", flexDirection: "column", gap: 8 }}>
        <h1 style={{ color: "white", fontSize: 54, fontWeight: 800, margin: 0, letterSpacing: "-0.03em" }}>
          {title}
        </h1>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <span style={{ color: supportColor, fontSize: 24, fontWeight: 700, letterSpacing: "0.1em" }}>
            {subtitle}
          </span>
          <div style={{ width: 6, height: 6, borderRadius: "50%", backgroundColor: "white", opacity: 0.3 }} />
          <span style={{ color: "white", opacity: 0.5, fontSize: 20, fontWeight: 500 }}>
            MALLOY STUDIO
          </span>
        </div>
      </div>

      {/* Vignette for Cinematic Depth */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "radial-gradient(circle at center, transparent 30%, rgba(0,0,0,0.8) 120%)",
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default XAUUSDChart;